const extraViews={};
const views=[['templates','模板管理','准备'],['ship','船舶档案',''],['voyage','本次航次',''],['profiles','船员档案','人员'],['arrival','进港船员名单',''],['departure','离港船员名单',''],['effects','船员个人物品','专项资料'],['ports','港口历史与计划',''],['stores','船舶物料',''],['health','健康申报及附表',''],['passengers','旅客名单',''],['medicines','药品名单',''],['nil','NIL 各项申报',''],['vaccines','疫苗有效日期',''],['check','检查、预览与下载','输出'],['mapping','字段映射',''],['help','使用说明与限制','']];
let viewTitle=v=>v==='settings'?'总设置':v==='plannedPorts'?'未来港口计划':views.find(x=>x[0]===v)?.[1]||v;
function updateMeters(){if(!$('#templateMeter'))return;$('#templateMeter').textContent=CONFIG.templates.filter(c=>chosenTemplate(c.id)).length+' / 10';$('#crewMeter').textContent=state.arrival.length+' → '+state.departure.length;$('#fillMeter').textContent=lastChecks?(lastChecks.errors?lastChecks.errors+' 项错误':'10 / 10 可生成'):'待检查'}
function field(key,label,opts={}){const value=getPath(state,key);return `<label class="${opts.full?'full':''}"><span>${esc(label)}${opts.required?' <b class="critical">*</b>':''}</span>${opts.select?`<select data-bind="${esc(key)}">${opts.select.map(([v,l])=>`<option value="${esc(v)}" ${String(value)===v?'selected':''}>${esc(l)}</option>`).join('')}</select>`:`<input data-bind="${esc(key)}" type="${opts.type||'text'}" value="${esc(value)}" ${opts.placeholder?'placeholder="'+esc(opts.placeholder)+'"':''}>`}${opts.hint?`<div class="hint">${esc(opts.hint)}</div>`:''}</label>`}
function heading(title,intro){return `<h1>${esc(title)}</h1><p class="intro">${intro}</p>`}
function renderPageKey(){return currentView+(currentView==='ports'&&typeof portTab!=='undefined'?':'+portTab:currentView==='stores'&&typeof storeFilter!=='undefined'?':'+storeFilter:'')}
function scrollRegionKey(node,index){const grid=node.querySelector('table[data-grid]');return grid?'grid:'+grid.dataset.grid+':'+(node.closest('[data-store-location]')?.dataset.storeLocation||''):node.classList.contains('plan-timeline')?'plan-timeline':'region:'+index}
function captureRenderPosition(content){return {top:content.scrollTop,left:content.scrollLeft,windowX:window.scrollX,windowY:window.scrollY,regions:new Map([...content.querySelectorAll('.tablewrap,.plan-timeline')].map((node,index)=>[scrollRegionKey(node,index),{top:node.scrollTop,left:node.scrollLeft}]))}}
function restoreRenderPosition(content,saved){for(const [index,node]of [...content.querySelectorAll('.tablewrap,.plan-timeline')].entries()){const position=saved.regions.get(scrollRegionKey(node,index));if(position){node.scrollTop=position.top;node.scrollLeft=position.left}}content.scrollTop=saved.top;content.scrollLeft=saved.left;if(window.scrollX!==saved.windowX||window.scrollY!==saved.windowY)window.scrollTo({left:saved.windowX,top:saved.windowY,behavior:'instant'})}
function render(){
 const content=$('#content'),key=renderPageKey(),position=content.dataset.renderKey===key?captureRenderPosition(content):null,nav=$('#nav'),navTop=nav.scrollTop;
 $('#nav').innerHTML=views.map(([v,label,g])=>(g?`<div class="nav-group">${g}</div>`:'')+`<button class="nav ${v===currentView?'active':''}" data-action="navigate" data-view="${v}">${label}</button>`).join('');$('#topTitle').textContent=viewTitle(currentView);
 const fn={...extraViews,settings:()=>settingsView(),templates:templateView,ship:shipView,voyage:voyageView,profiles:()=>tableView('profiles'),arrival:()=>tableView('arrival'),departure:()=>tableView('departure'),effects:()=>tableView('effects'),ports:()=>tableView('ports'),stores:()=>tableView('stores'),health:healthView,passengers:()=>tableView('passengers'),medicines:()=>tableView('medicines'),nil:nilView,vaccines:()=>tableView('vaccines'),check:checkView,mapping:()=>typeof mappingView==='function'?mappingView():legacyMappingView(),help:helpView}[currentView];$('#content').innerHTML=fn?fn():'';enhanceView();updateMeters();
 content.dataset.renderKey=renderPageKey();if(position)restoreRenderPosition(content,position);else{content.scrollTop=0;content.scrollLeft=0}nav.scrollTop=navTop;
}
function templateView(){return heading('模板管理','默认载入 10 份内置空模板。可导入自己的 XLSX、ZIP 或文件夹，并保存为常用配置。')+(typeof defaultsPanel==='function'?defaultsPanel():'')+`<div class="card"><div class="row"><button class="primary" data-action="pickTemplates">更换 / 添加 XLSX 或 ZIP</button><button data-action="pickFolder">选择模板文件夹</button><button data-action="loadProject">导入工程</button><button data-action="clearTemplates">清空模板选择</button></div><label class="checkline"><input id="replaceMatchingTemplates" type="checkbox" checked><span>导入时替换同类模板；取消后可同时保留版本并检查重复。</span></label><div class="note">内置模板来自本次提供的空模板包，历史动态资料已清理。导入的模板保留原始内容，但历史日期、港口、库存、健康答案与名单不会自动当成本次资料。</div></div>`+(importProblems.length?`<div class="errorbox"><b>文件读取提示</b><ul>${importProblems.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><button class="small" data-action="dismissImportProblems">清除这些提示</button></div>`:'')+`<div class="tablewrap"><table><thead><tr><th>模板</th><th>识别结果</th><th>工作表及原容量</th><th>操作</th></tr></thead><tbody>${CONFIG.templates.map(c=>{const list=templates.get(c.id)||[];return `<tr><td><b>${c.id}. ${esc(c.title)}</b><div class="muted">${esc(c.filename)}</div></td><td><span class="badge ${list.length===1?'ok':list.length?'err':'warn'}">${list.length===1?'已识别':list.length?'重复 '+list.length+' 个':'缺失'}</span>${list.map(e=>`<div class="keyline">${esc(e.name)} <span class="muted">${(e.bytes.length/1024).toFixed(1)} KB</span>${list.length>1?` <button class="small" data-action="chooseTemplate" data-id="${c.id}" data-token="${e.token}">保留此版本</button>`:''}<button class="small" data-action="removeTemplate" data-id="${c.id}" data-token="${e.token}">移除</button></div>`).join('')}</td><td>${c.sheets.map(s=>`${esc(s.name)}${s.table?'：'+s.table.rows.length+' 行':''}${s.clear?'：清空历史记录':''}`).join('<br>')}</td><td><button class="small" data-action="inspectTemplate" data-id="${c.id}" ${list.length!==1?'disabled':''}>可视化查看</button></td></tr>`}).join('')}</tbody></table></div><div class="card"><h2>从模板读取档案</h2><p>先查看候选值再确认；档案导入与本次名单选入是两个独立步骤。</p><div class="row"><button data-action="pickShipPdf">读取船舶资料 PDF</button><button data-action="shipCandidates">读取船舶静态资料</button><button data-action="importTemplatePeople">导入船员档案</button><button data-action="importTemplateVaccines">导入疫苗档案</button></div></div>`}
function shipView(){return heading('船舶档案','公共资料填写一次，写入各表实际对应位置。确认后可以跨航次复用。支持本地读取 Ship Particulars PDF，逐项核对后导入。')+shipPdfSourceNote()+`<div class="card"><div class="row spaced"><h2>基本资料</h2><div class="row"><button class="primary" data-action="pickShipPdf">导入船舶资料 PDF</button><button data-action="shipCandidates">从已选择模板读取候选值</button></div></div><div class="grid">${field('ship.name','船名',{required:true})}${field('ship.imo','IMO 编号',{placeholder:'7 位数字，按文本保存'})}${field('ship.callSign','呼号')}${field('ship.flag','船旗 / 国籍',{required:true})}${field('ship.registry','船籍港')}${field('ship.company','船公司')}${field('ship.netTonnage','净登记吨位',{placeholder:'例如 23242；填写本船实际资料'})}${field('ship.master','船长姓名',{required:true,hint:'须与进港、离港本次名单中的姓名唯一匹配。排序不会影响船长公式。'})}</div><label class="checkline"><input type="checkbox" data-bind="ship.confirmed" ${state.ship.confirmed?'checked':''}><span>我已确认以上船舶静态资料及船长姓名。</span></label></div><div class="note">模板内船名的大小写、Ø / OE 写法和船公司拼写存在差异，请选择本次统一使用的正式写法。</div>`}
function voyageView(){return heading('本次航次','进港、离港分别维护日期、港口与名单。其余清单按所选申报阶段使用对应资料；健康申报固定使用进港资料。')+`${typeof voyagePlanPanel==='function'?voyagePlanPanel():''}<div class="card"><h2>到离港资料</h2><div class="grid">${field('voyage.mode','专项清单使用的申报阶段',{select:[['arrival','进港资料及进港名单'],['departure','离港资料及离港名单']]})}${field('voyage.arrivalPort','到港港口',{required:true})}${field('voyage.departurePort','离港港口',{required:true,hint:'通常与到港港口相同，请明确填写。'})}${field('voyage.arrivalDate','到港日期',{type:'date',required:true})}${field('voyage.departureDate','离港日期',{type:'date',required:true})}${field('voyage.lastPort','上一港',{required:true})}${field('voyage.nextPort','下一港',{required:true})}${field('voyage.stay','停留时间',{placeholder:'例如 1 DAYS；不自动计算'})}${field('voyage.month','药品文件本次年月',{type:'month',required:true})}${field('voyage.signArrival','进港签署日期',{type:'date',hint:'空白时跟随本次到港日期。'})}${field('voyage.signDeparture','离港签署日期',{type:'date',hint:'空白时跟随本次离港日期。'})}${field('voyage.storage','物料总存放位置说明',{hint:'可空。空白时从物料分组生成概括说明；详细分类列在物料区。'})}</div></div><div class="card"><h2>跨航次复用</h2><p>清空后保留已确认船舶档案、船员档案（含疫苗有效日期）、原模板与映射；本次名单、库存、历史港口、个人物品、申报答案和日期会清空；未来港口计划和自定义港口保留。</p><button class="danger" data-action="resetVoyage">清空本次航次资料</button></div><div class="card"><h2>图片与签名</h2><p>这批实际模板的 9 张图片均为船公司标识，没有检测到签名图片。标识默认保留。</p><label class="checkline"><input type="checkbox" data-bind="preferences.reuseSignatures" ${state.preferences.reuseSignatures?'checked':''}><span>沿用已标记为签名的图片（默认不沿用；无签名标记时不影响船公司标识）。</span></label><button data-action="manageSignatures">查看图片并标记签名</button></div>`}
function getRows(view){if(view==='profiles')return state.people;if(['arrival','departure'].includes(view))return roster(view);if(view==='cases')return caseRecords();if(['effects','vaccines'].includes(view))return sectionRecords(view,view==='effects'?3:10);return state[view]||[]}
function declarationControls(view){const v=state.declarations[view];return `<div class="row"><label style="min-width:240px"><span>本次记录状态</span><select data-declaration="${view}"><option value="" ${!v?'selected':''}>未确认（须选择）</option><option value="records" ${v==='records'?'selected':''}>有记录，按表格生成</option><option value="none" ${v==='none'?'selected':''}>无记录，明确生成 NIL</option></select></label><span class="muted">空白、NIL 与数字 0 分别保存；选“无”前请先清空已有记录。</span></div>`}
function tableView(view){
 if(view==='ports'&&typeof portWorkspace==='function')return portWorkspace();
 if(view==='stores'&&typeof storesWorkspace==='function')return storesWorkspace();
 const descriptions={profiles:'档案以稳定人员标识保存。导入档案后，仍须明确选入本次进港或离港名单。档案修改会同步到未设本次覆盖值的字段。',arrival:'独立维护进港名单。此处编辑形成进港专用值；其他人员资料按档案关联。',departure:'独立维护离港名单，可复制进港名单后移除下船人员、加入上船人员。此处编辑形成离港专用值。',effects:'按本次申报阶段的船员名单显示，姓名和职务自动关联。香烟、烟酒数量和其他物品必须明确填写，0 与 NIL 均保留原含义。',ports:'逐项维护历史挂靠港。输出最近 10 条，本表保持 1 页打印。',stores:'逐项维护物料及位置。生成时按存放位置先列大类，再列物料、数量和单位；跨页重复分类标题，不逐项重复存放位置。',passengers:'按实际旅客填写，或明确选择无旅客。不会自动从船员名单复制人员。',medicines:'按实际库存填写。到期日期支持 YYYY-MM-DD 或明确填 N/A；过期只提示核查，不修改数量与日期。',vaccines:'按稳定人员标识关联疫苗资料，排序不会串人。此模板列为“有效日期”，可填写日期、NIL、N/A 或终身。'};
 const linked=['effects','vaccines'].includes(view),rows=getRows(view),count=rows.length;
 return heading(viewTitle(view),esc(descriptions[view]||''))+`<div class="card">${state.declarations.hasOwnProperty(view)?declarationControls(view):''}<div class="row spaced"><div class="row">${!linked?`<button class="primary" data-action="addRow" data-view="${view}">添加${['profiles','arrival','departure'].includes(view)?'人员':'记录'}</button>`:''}${['arrival','departure'].includes(view)?`<button data-action="choosePeople" data-view="${view}">从档案选择人员</button><button data-action="resetOverrides" data-view="${view}">清除本名单覆盖值</button>`:''}${view==='departure'?'<button data-action="copyArrival">复制进港名单</button>':''}<button data-action="pickData" data-view="${view}">导入 Excel / CSV</button><button data-action="pasteData" data-view="${view}">批量粘贴</button><button data-action="exportCsv" data-view="${view}">导出编辑数据 CSV</button></div><span class="muted">${count} ${linked?'人':'条'}${linked?' · 跟随'+(state.voyage.mode==='arrival'?'进港':'离港')+'名单':''}</span></div>${view==='effects'?`<div class="grid two" style="margin-top:15px">${field('effectsDeclaration','应税或受限物品申报',{placeholder:'例如 NIL；需本人核查后填写'})}<div class="row"><button data-action="nilAllEffects">将本次所有个人物品明确设为 NIL</button></div></div>`:''}${view==='vaccines'?'<p class="muted">有效日期的历史值仅在明确导入档案或工程后出现；请核查后使用。</p>':''}${['arrival','departure'].includes(view)?'<p class="muted">进港与离港名单独立保存。新内置模板按原工作表输出；旧模板若包含历史附表，仍按对应映射清理。</p>':''}${editableTable(view)}<p class="muted">日期可输入 YYYY-MM-DD 或 DD/MM/YYYY。可直接在单元格粘贴制表符分隔的多行内容；文本形式的证件号码保留前导零。表头的排序按钮与 ↑ ↓ 可调整顺序。</p></div>`
}
function editableTable(view){const rows=getRows(view),cols=schema[view],linked=['effects','vaccines'].includes(view);return `<div class="tablewrap"><table data-grid="${view}"><thead><tr><th>#</th>${cols.map(([k,l,t])=>`<th>${esc(l)}${t!=='readonly'?` <button data-action="sortRows" data-view="${view}" data-field="${k}" title="按此列升降序排序">↕</button>`:''}</th>`).join('')}<th>操作</th></tr></thead><tbody>${rows.map((r,i)=>`<tr data-row-id="${esc(r.id)}"><td class="num">${i+1}</td>${cols.map(([k,l,type])=>{const read=type==='readonly'||(view==='cases'&&r.personId&&['name','rank','sex','nationality','embarkPort','embarkDate'].includes(k));const attrs=`data-table="${view}" data-id="${esc(r.id)}" data-field="${k}"`;return `<td>${type==='person'?`<select ${attrs}><option value="">独立填写 / 非船员</option>${state.people.map(p=>`<option value="${esc(p.id)}" ${r.personId===p.id?'selected':''}>${esc(p.name||'未命名')} · ${esc(p.passport||p.seamanBook||p.id.slice(0,8))}</option>`).join('')}</select>`:`<input ${attrs} value="${esc(r[k]??'')}" aria-label="第 ${i+1} 行 ${esc(l)}" ${read?'readonly':''} ${dateFields.has(k)?'placeholder="日期 / NIL"':''}>`}</td>`}).join('')}<td class="tools">${!linked?`<button class="small" data-action="moveRow" data-view="${view}" data-id="${esc(r.id)}" data-dir="-1" aria-label="上移">↑</button> <button class="small" data-action="moveRow" data-view="${view}" data-id="${esc(r.id)}" data-dir="1" aria-label="下移">↓</button> <button class="small danger" data-action="deleteRow" data-view="${view}" data-id="${esc(r.id)}">删除</button>`:`<span class="muted" title="${esc(r.id)}">已关联</span>`}</td></tr>`).join('')||`<tr><td colspan="${cols.length+2}" class="empty">${linked?'请先在本次名单中选入船员。':'暂无记录。添加、导入或粘贴后即可编辑。'}</td></tr>`}</tbody></table></div>`}
function healthView(){return heading('健康申报及病例附表','保留原表 9 个问题（包括原表重复列出的死亡问题），必须逐项选择 Yes / No。病例写入原附表；超量时插入行，主表和附表分别一页打印。')+`<div class="card"><h2>健康问题</h2><div class="grid two">${healthQuestions.map((q,i)=>field('health.q'+(i+1),q,{select:[['','尚未回答'],['Yes','Yes / 是'],['No','No / 否']]})).join('')}${field('health.measures','第 7 问：措施类别、地点和日期',{full:true})}${field('health.stowawayPlace','第 8 问：偷渡人员登船地点',{full:true})}</div></div><div class="card"><h2>卫生证书及会签</h2><div class="grid">${field('health.certType','证书类别',{required:true,placeholder:'填写证书正式名称'})}${field('health.certDate','签发日期',{type:'date',required:true})}${field('health.certPlace','签发地点',{required:true})}${field('health.certExpiry','证书到期日期（只用于核查）',{type:'date',hint:'原模板无此字段，不写入 Excel。'})}${field('health.surgeon','船医 / 会签人',{required:true,placeholder:'无则明确填写 NIL'})}</div></div><div class="card"><h2>病例附表 · healthback</h2>${declarationControls('cases')}<div class="row" style="margin-top:15px"><button class="primary" data-action="addRow" data-view="cases">添加病例</button><button data-action="pickData" data-view="cases">导入 Excel / CSV</button><button data-action="pasteData" data-view="cases">批量粘贴</button><button data-action="exportCsv" data-view="cases">导出病例 CSV</button></div><p class="muted">选择关联船员后，姓名、职务、性别、国籍、上船港口和日期优先随进港名单同步（未在名单时使用档案）；年龄可按出生日期推算，也可明确填写。</p>${editableTable('cases')}</div>`}
function nilView(){return heading('NIL 各项申报','每项须由用户明确填写。NIL 表示无，0 为数字零；有申报内容则填写实际情况。旅客和健康答案会进行一致性检查。')+`<div class="card"><div class="row spaced"><h2>10 项申报</h2><button data-action="nilAll">将这 10 项明确设为 NIL</button></div><div class="grid two">${nilKeys.map((k,i)=>field('nil.'+k,nilLabels[i],{placeholder:'未填写；输入 NIL、0 或实际内容'})).join('')}</div><div class="note">原模板未设独立答案表头，答案映射到 K22:K31 的空白区域。填写较长内容后请核对 Excel/WPS 打印预览。</div></div>`}
function checkView(){const ch=lastChecks||checkAll();return heading('检查、数据预览与下载','每份文件独立检查，缺少必填资料或映射失效会阻止该文件生成。整包必须 10 份全部成功。')+`<div class="card"><div class="row spaced"><div><span class="summary">${ch.errors?ch.errors+' 项错误':'10 份文件可生成'}</span><p class="muted">${ch.warnings} 项核查警告。过期证件与药品保留原数据，不擅自改写。</p></div><button data-action="validate">重新检查</button></div><div class="preview-label">页面预览仅为待写入数据预览，不是 Excel 打印预览。保留原版式；最终请在 Excel/WPS 中检查打印效果。公式打开文件后自动重算。</div>${generated.size?`<p>本轮已生成 ${generated.size} / 10 份 XLSX。</p>`:''}</div><div class="statuscards">${ch.results.map(r=>`<div class="card"><div class="row spaced"><h2>${r.id}. ${esc(r.title)}</h2><span class="badge ${r.errors.length?'err':'ok'}">${r.errors.length?'需修正 '+r.errors.length+' 项':generated.has(r.id)?'已生成':'可生成'}</span></div>${r.errors.length?`<ul class="issues critical">${r.errors.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul>`:''}${r.warnings.length?`<details open><summary>${r.warnings.length} 项核查警告</summary><ul class="issues">${r.warnings.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></details>`:''}${r.notes.length?`<details><summary>输出说明</summary><ul class="issues">${r.notes.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></details>`:''}<div class="row"><button class="small" data-action="previewFile" data-id="${r.id}">待写入数据预览</button><button class="small" data-action="generateOne" data-id="${r.id}" ${r.errors.length?'disabled':''}>下载本份 XLSX</button></div></div>`).join('')}</div>`}
function legacyMappingView(){return heading('模板 → 工作表 → 字段 → 位置','配置与页面逻辑分开，随工程保存。配置同时包含健康附表和旅客表的历史 NIL 绘图控制。模板结构或合并区域变化时，会阻止生成；请据实际模板修改映射，不能凭文件名猜测。')+`<div class="card"><div class="row"><button data-action="editMapping">编辑完整映射 JSON</button><button data-action="exportMapping">导出映射 JSON</button><button data-action="importMapping">导入映射 JSON</button><button data-action="restoreMapping">恢复本批原始映射</button></div><p class="muted">明细表的 rows 为原容量；超量时插入行，整表缩放为一页。clear 为必须清空的动态区域；不要遗漏附表。</p></div>${CONFIG.templates.map(c=>`<div class="card"><h2>${c.id}. ${esc(c.title)}</h2>${c.sheets.map(s=>`<h3>${esc(s.name)}</h3><div class="tablewrap"><table><thead><tr><th>字段 / 数据源</th><th>单元格 / 明细区域</th><th>说明</th></tr></thead><tbody>${s.fields.map(f=>`<tr><td><code>${esc(f.key)}</code></td><td>${esc(f.cell)}</td><td>${esc(f.type||'文本')}${f.prefix?' · '+esc(f.prefix):''}</td></tr>`).join('')}${s.table?`<tr><td><b>${esc(s.table.source)}</b></td><td>行 ${s.table.rows[0]}–${s.table.rows.at(-1)}<br>${Object.entries(s.table.columns).map(([f,col])=>esc(f)+' → '+col).join('；')}</td><td>每页 ${s.table.rows.length} 行，超量插行并缩放为一页</td></tr>`:''}${s.clear?`<tr><td>清除历史数据</td><td>${esc(s.clear.join('、'))}</td><td>保留工作表与样式</td></tr>`:''}${s.page?`<tr><td>本次页码</td><td>${esc(s.page)}</td><td>当前页 / 本表总页数</td></tr>`:''}</tbody></table></div>`).join('')}</div>`).join('')}`}
function helpView(){return heading('使用说明与实际限制','离线文件夹 / 单文件均可使用。推荐 Chrome / Edge 普通窗口。无需安装其他软件。')+(typeof newHelpPanel==='function'?newHelpPanel():'')+`<div class="card"><h2>使用顺序</h2><ol><li>内置的 10 份空模板自动载入。需要替换时，选择自己的 XLSX、ZIP 或整个文件夹。</li><li>读取并确认船舶档案；导入船员档案，再分别选入进港与离港名单。上下船变动在两份名单中编辑。</li><li>填写本次航次与专项资料。可导入 XLSX / UTF-8 或 GB18030 CSV、粘贴表格、手工编辑。日期建议使用 YYYY-MM-DD。</li><li>逐项回答健康问题，填写病例附表；无旅客、无物料等情况须明确选择“无记录”。NIL 与 0 保留区分。</li><li>检查每份文件，查看待写入数据预览，再下载单份 XLSX 或整包 ZIP。</li><li>保存工程到工程文件夹，下次自动恢复；另存为可保留独立备份。总设置中的“导出工程”还可选择不含模板，恢复时须核对模板版本。</li></ol><p>修改输入后，先前生成缓存会作废。默认需要主动保存；可在左下角总设置启用定时保存。Windows 启动器默认使用解压目录旁的“保存工程”。</p></div><div class="card"><h2>读取船舶资料 PDF</h2><p>在“船舶档案”点击“导入船舶资料 PDF”，选择文字型 PDF，核对各字段、来源页和公司用途后导入。支持提取船名、IMO、呼号、船旗、船籍港、船公司和净吨；PDF 中未列出的字段不覆盖现值。船长姓名不会从电话或邮箱推断。</p><p>国际吨位表读取 NET 列，避免误用 GROSS 或苏伊士 / 巴拿马吨位。OWNER、管理公司和租家分别显示供选择。设计定员和建造日期不作为本次人数或航次日期。</p><p>PDF.js 5.6.205（Apache-2.0）及文字读取所需字体资源已随包提供，离线读取，无上传。PDF 原文件不嵌入 HTML，也不保存到工程；工程仅保存导入字段和来源记录。暂不支持扫描件 OCR、加密 PDF，最大 25MB、50 页。推荐当前版本 Chrome / Edge。</p></div><div class="card"><h2>数据导入与人员关联</h2><p>XLSX、CSV 导入先选择工作表与表头行，再核对每一列的字段映射。证件号码按文本处理；如果原始 Excel/CSV 已经丢失前导零，工具无法推断恢复。XLSX 中纯零数字格式可以还原显示的前导零。</p><p>人员档案使用 UUID；本次两份名单独立保存覆盖值。物品和疫苗通过 UUID 关联，不按行号匹配。个人资料导入用唯一姓名或人员标识匹配，重名时拒绝自动配对。</p><p>批量粘贴无表头内容时，取消“首行为表头”，再手工选择列。直接在表格单元格粘贴多行多列内容会从该单元格开始填写。</p></div><div class="card"><h2>原模板与生成策略</h2><p>已检查实际 10 文件共 13 工作表，包含健康申报附表，以及两份船员文件的历史 Sheet1。只修改映射数据区，使用 inlineStr 写入字符串，避免修改共享字符串时串改无关单元格；不再引用的旧共享字符串被清空。</p><p>保留原样式、合并、行高、列宽、图片、原工作表相对顺序和打印设置。续页复制完整原工作表并追加到末尾；每页表头、签署区和原打印区域保留，页码单独更新。两份历史 Sheet1 的 A1:M2 全部清空。有旅客或病例时，移除对应旧 NIL 绘图及旅客斜线；明确无记录时才沿用。</p><p>物料按名称、数量、单位输出，原 F11 为官方使用栏，不挪作存放地点。先输出存放位置大类标题，再列名称、数量和单位，不逐项重复 Storage 行。同类跨页时重复大类标题，标题至少与一条物料同页。原分类与数量属于历史资料，默认不导入本次库存。</p><p>已知的船长和签署日期公式保留为公式并更新缓存；其他公式清除旧缓存，标记 Excel/WPS 打开后自动重算。浏览器不承担完整 Excel 公式引擎。</p></div><div class="card"><h2>交付验证范围</h2><p>使用这 10 个实际模板，在浏览器完全离线状态验证了单份与 ZIP 下载、进出港名单差异、所有明细超量续页、减少记录清理、健康附表、前导零、稳定人员关联及工程恢复。40 份测试 XLSX 通过 XML、内容、样式与打印设置对照，并进行工作表渲染检查。</p><p>原生 Excel 自动化被当前系统组策略限制；尚未完成原生 Excel/WPS 打开与实际打印测试，不能把数据预览视作这项验证。</p></div><div class="card"><h2>限制</h2><ul><li>预览是数据预览，不模拟 Excel 打印排版。任意长文本可能超出原行高，需要在 Excel/WPS 中核对后调整。</li><li>支持标准、未加密的 .xlsx；不支持 .xls、.xlsm、密码工作簿或带宏模板。单 XLSX 最大 35MB，ZIP 最大 50MB，单次导入最多 10,000 行、100 列。</li><li>新模板若更改工作表、合并区域或数据位置，须调整映射。无法识别的模板不会默默套用。</li><li>原模板图片为船公司标识，默认保留。未来模板若包含签名，请在图片管理中明确标记，再选择是否沿用。</li><li>工具按本次输入生成文件，不判断申报内容是否满足具体港口要求。</li></ul></div><div class="card"><h2>本地与依赖</h2><p>依赖 JSZip 3.10.1（MIT）已完整内嵌。文件读取、解压、XML 修改和下载均在浏览器内存中完成；CSP 禁止网络连接，无 CDN、分析统计或上传接口。</p><div class="row"><button data-action="saveProject">保存工程</button><button data-action="loadProject">导入工程</button><button data-action="exportMapping">导出映射</button></div></div>`}

function dataRef(view,id){if(view==='profiles')return getPerson(id);if(['arrival','departure'].includes(view)){const e=state[view].find(x=>x.personId===id);return e?.overrides}if(view==='effects')return state.effects[id]??={};if(view==='vaccines'){const p=getPerson(id);return p?(p.vaccines??={}):null}return state[view]?.find(x=>x.id===id)}
function addRow(view,noRender=false){const id=uid();if(['profiles','arrival','departure'].includes(view)){state.people.push({id,...Object.fromEntries(schema.profiles.map(([k])=>[k,''])),vaccines:{}});if(view!=='profiles')state[view].push({personId:id,overrides:{}})}else{const row={id,...Object.fromEntries(schema[view].map(([k])=>[k,'']))};if(!noRender&&['ports','plannedPorts'].includes(view))Object.assign(row,{security:'1',remarks:'CARGO OPERATION'});state[view].push(row);if(state.declarations.hasOwnProperty(view))state.declarations[view]='records'}if(!noRender){changed();render()}return id}
function mutateCell(view,id,key,value){const ref=dataRef(view,id);if(!ref)throw Error('找不到对应记录');ref[key]=value;if(view==='cases'&&key==='personId')render();changed()}
function removeRow(view,id){if(view==='profiles'){if(state.arrival.some(r=>r.personId===id)||state.departure.some(r=>r.personId===id)||state.cases.some(r=>r.personId===id))throw Error('该档案仍被名单或病例关联，请先移除关联。');state.people=state.people.filter(p=>p.id!==id);delete state.effects[id]}else if(['arrival','departure'].includes(view))state[view]=state[view].filter(x=>x.personId!==id);else state[view]=state[view].filter(x=>x.id!==id);changed();render()}
function moveRows(view,id,dir){const a=view==='profiles'?state.people:state[view];const i=a.findIndex(x=>(x.personId||x.id)===id),j=i+Number(dir);if(i<0||j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];changed();render()}
const sortDirections={};function sortRows(view,key){const dir=sortDirections[view+key]===1?-1:1;sortDirections[view+key]=dir;let arr=state[view==='profiles'?'people':view];const display=new Map(getRows(view).map(r=>[r.id,r]));if(['effects','vaccines'].includes(view))arr=state[state.voyage.mode];arr.sort((a,b)=>{const x=display.get(a.personId||a.id)?.[key]??'',y=display.get(b.personId||b.id)?.[key]??'';return String(x).localeCompare(String(y),'zh-CN',{numeric:true})*dir});changed();render()}
function choosePeople(side){const present=new Set(state[side].map(x=>x.personId));modal('从档案选择'+(side==='arrival'?'进港':'离港')+'船员',`<p>仅勾选本次在船人员。选入名单后可独立编辑。</p><div class="row"><button data-action="selectAllPeople">勾选全部可选人员</button></div><div class="tablewrap"><table><thead><tr><th>本次选入</th><th>姓名</th><th>职务</th><th>护照 / 人员标识</th></tr></thead><tbody>${state.people.map(p=>`<tr><td><input type="checkbox" data-choose-person="${esc(p.id)}" ${present.has(p.id)?'checked disabled':''}></td><td>${esc(p.name)}</td><td>${esc(p.rank)}</td><td>${esc(p.passport||p.id)}</td></tr>`).join('')||'<tr><td colspan="4">请先添加或导入船员档案。</td></tr>'}</tbody></table></div>`,`<button data-action="closeModal">取消</button><button class="primary" data-action="applyPeople" data-view="${side}">选入本次名单</button>`)}
function shipCandidates(){
 const values={};const take=(id,cell,key,clean=v=>v)=>{const e=chosenTemplate(id);if(!e)return;const value=clean(cellText(e.book.sheets[0].cells.get(cell),e.book.strings));if(!isBlank(value))(values[key]??=[]).push({value,source:e.name+'!'+cell})};
 take(1,'A5','name');take(9,'E7','name');take(1,'A7','flag');take(9,'E11','flag');take(9,'J9','imo');take(10,'B10','imo');take(9,'J7','callSign');take(9,'E9','registry');take(7,'B6','company');take(10,'B6','company');take(6,'D8','netTonnage');take(6,'H7','master');
 const labels={name:'船名',flag:'船旗',imo:'IMO 编号',callSign:'呼号',registry:'船籍港',company:'船公司',netTonnage:'净吨',master:'船长姓名'};
 modal('核对船舶静态资料候选值',`<p>只读取船舶档案，不读取历史港口、日期、数量或申报答案。存在不同写法的字段可自行选择或返回手工填写。</p><div class="tablewrap"><table><thead><tr><th>字段</th><th>本次选用值</th><th>原模板来源</th></tr></thead><tbody>${Object.entries(labels).map(([k,l])=>{const a=values[k]||[],all=[...new Set([...(state.ship[k]?[state.ship[k]]:[]),...a.map(x=>x.value)])];return `<tr><td>${l}</td><td><select data-candidate="${k}"><option value="">暂不导入</option>${all.map(v=>`<option value="${esc(v)}" ${v===(state.ship[k]||all[0])?'selected':''}>${esc(v)}</option>`).join('')}</select></td><td>${a.map(x=>esc(x.source)+'：'+esc(x.value)).join('<br>')||'未从已选模板读取到值'}</td></tr>`}).join('')}</tbody></table></div>`,`<button data-action="closeModal">取消</button><button class="primary" data-action="applyShipCandidates">导入所选静态值，去确认档案</button>`)
}
function originalRecords(id){const c=CONFIG.templates.find(c=>c.id===id),e=chosenTemplate(id);if(!e)throw Error('请先选择对应模板 '+id);const t=c.sheets[0].table,sh=e.book.sheets[0];return t.rows.map(row=>Object.fromEntries(Object.entries(t.columns).filter(([k])=>k!=='seq').map(([k,col])=>{let v=cellText(sh.cells.get(col+row),e.book.strings);if(dateFields.has(k)){if(/^\d{4,5}(\.\d+)?$/.test(v))v=fromSerial(v,e.book.date1904);else v=dateValue(v)||v}return [k,v]}))).filter(r=>r.name)}
let pendingPeople=[];
function importTemplatePeople(){const id=chosenTemplate(1)?1:2;pendingPeople=originalRecords(id);modal('确认导入历史船员档案',`<div class="note warn">这些人员来自历史模板。导入后仅保存到档案，不自动选入本次进港或离港名单。附加历史表不作为本次名单导入；请核对本次实际人员。</div><div class="tablewrap"><table><thead><tr><th>姓名</th><th>职务</th><th>护照号</th><th>上船日期</th></tr></thead><tbody>${pendingPeople.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.rank)}</td><td>${esc(p.passport)}</td><td>${esc(p.signOnDate)}</td></tr>`).join('')}</tbody></table></div>`,`<button data-action="closeModal">取消</button><button class="primary" data-action="applyTemplatePeople">确认导入 ${pendingPeople.length} 份档案</button>`)}
function matchPerson(row){const identified=[];if(row.personId){const p=getPerson(row.personId);if(!p)throw Error('人员标识不存在：'+row.personId);identified.push(p)}for(const key of ['passport','seamanBook'])if(row[key]){const found=state.people.filter(p=>p[key]&&norm(p[key])===norm(row[key]));if(found.length>1)throw Error('人员匹配不唯一：'+row[key]+'。请先核对重复证件。');identified.push(...found)}if(new Set(identified.map(p=>p.id)).size>1)throw Error('人员标识、护照或海员证指向不同人员：'+(row.name||row.personId||'此行')+'。请核对后重新导入。');if(identified.length)return identified[0];const found=row.name?state.people.filter(p=>norm(p.name)===norm(row.name)):[];if(found.length>1)throw Error('人员匹配不唯一：'+row.name+'。请提供人员标识或唯一证件号码。');return found[0]}
function upsertProfile(row){let p=matchPerson(row);if(!p){p={id:uid(),vaccines:{}};state.people.push(p)}for(const [k]of schema.profiles)if(row[k]!==undefined)p[k]=String(row[k]);return p}
