function normalizedImportValue(key,value,date1904=false){let v=String(value??'').trim();if(dateFields.has(key)){if(/^\d{4,5}(\.\d+)?$/.test(v))return fromSerial(v,date1904);return dateValue(v)||v}return v}
function applyImportedRows(view,rows,mode){
 const backup=structuredClone(state);const linkedSeen=new Set();try{
  if(rows.length>10000)throw Error('一次最多导入 10,000 条');if(!rows.length)throw Error('没有可导入的数据行');
  if(['arrival','departure'].includes(view)&&mode==='replace')state[view]=[];
  else if(!['profiles','arrival','departure','effects','vaccines'].includes(view)&&mode==='replace')state[view]=[];
  for(const [i,row]of rows.entries()){
   if(['profiles','arrival','departure'].includes(view)){if(!row.name)throw Error('第 '+(i+1)+' 行缺少姓名');let p;if(view==='profiles')p=upsertProfile(row);else{p=matchPerson(row);if(!p){p={id:uid(),vaccines:{},...row};state.people.push(p)}if(state[view].some(r=>r.personId===p.id))throw Error('本次名单重复人员：'+row.name);state[view].push({personId:p.id,overrides:{...row}})}}
   else if(['effects','vaccines'].includes(view)){const p=matchPerson(row);if(!p)throw Error('第 '+(i+1)+' 行无法关联现有船员：'+(row.name||row.personId||'未提供姓名'));if(linkedSeen.has(p.id))throw Error('导入包含重复人员：'+(row.name||p.id));linkedSeen.add(p.id);const allowed=schema[view].filter(x=>x[2]!=='readonly').map(x=>x[0]);const dest=view==='effects'?(state.effects[p.id]??={}):(p.vaccines??={});for(const k of allowed)if(row[k]!==undefined)dest[k]=row[k]}
   else state[view].push({id:uid(),...row});
  }
  if(state.declarations.hasOwnProperty(view))state.declarations[view]='records';changed();closeModal();render();toast('已导入 '+rows.length+' 条，请检查本次资料。');
 }catch(e){state=backup;throw e}
}
function applyDataImport(){const c=importContext,m=c.matrices[c.sheet],map=$$('[data-import-col]').map(s=>[+s.dataset.importCol,s.value]).filter(([,k])=>k);if(!map.length)throw Error('至少映射一列');if(new Set(map.map(([,k])=>k)).size!==map.length)throw Error('多列映射到同一字段，请只保留一列');const rows=m.rows.slice(c.header-1+(c.hasHeader?1:0),c.end||m.rows.length).filter(r=>map.some(([i])=>String(r[i]??'').trim()!=='')).map(r=>Object.fromEntries(map.map(([i,k])=>[k,normalizedImportValue(k,r[i],m.date1904)])));applyImportedRows(c.view,rows,$('#importMode').value)}
function applyGridPaste(target,text){const view=target.dataset.table,cols=schema[view],startCol=cols.findIndex(x=>x[0]===target.dataset.field),records=getRows(view),startRow=records.findIndex(r=>r.id===target.dataset.id),rows=parseDelimited(text),backup=structuredClone(state);try{if(rows.length+startRow>10000)throw Error('最多 10,000 行');if(['effects','vaccines'].includes(view)&&rows.length+startRow>records.length)throw Error('粘贴行数超过现有人员，请先在名单中选入人员');for(let i=0;i<rows.length;i++){let row=getRows(view)[startRow+i];if(!row){const id=addRow(view,true);row=getRows(view).find(r=>r.id===id)}for(let j=0;j<rows[i].length;j++){const col=cols[startCol+j];if(!col)throw Error('粘贴列数超出表格');if(col[2]==='readonly'||(view==='cases'&&row.personId&&['name','rank','sex','nationality','embarkPort','embarkDate'].includes(col[0])))continue;const dest=dataRef(view,row.id),value=normalizedImportValue(col[0],rows[i][j]);if(['ports','plannedPorts'].includes(view)&&['port','country'].includes(col[0])&&dest[col[0]]!==value){delete dest.portMeta;delete dest.locode;delete dest.countryCode}dest[col[0]]=value}}if(['ports','plannedPorts'].includes(view)&&typeof refreshLinkedPlan==='function')refreshLinkedPlan();if(state.declarations.hasOwnProperty(view))state.declarations[view]='records';changed();render();toast('已粘贴 '+rows.length+' 行')}catch(e){state=backup;throw e}}
function csvText(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function exportCsv(view){const cols=schema[view],linked=['effects','vaccines'].includes(view);download(csvText([[...(linked?['人员标识']:[]),...cols.map(x=>x[1])],...getRows(view).map(r=>[...(linked?[r.id]:[]),...cols.map(([k])=>r[k]??'')])]),viewTitle(view)+'.csv','text/csv;charset=utf-8')}

function toBase64(bytes){let s='';for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(s)}
function fromBase64(str){const s=atob(str),bytes=new Uint8Array(s.length);for(let i=0;i<s.length;i++)bytes[i]=s.charCodeAt(i);return bytes}
function saveProjectDialog(){modal('保存工程文件',`<p>工程保存船舶与船员档案、本次资料、稳定人员标识、图片选择和完整字段映射。PDF 导入后的字段和来源记录也会保存，PDF 原文件不包含在工程中。文件含个人资料，请自行妥善保存。</p><label class="checkline"><input id="includeProjectTemplates" type="checkbox" ${state.preferences.includeTemplates?'checked':''}><span>包含已选择的原始 XLSX 模板。勾选后可完整离线恢复；取消后使用恢复时已载入的模板，须核对是否相同版本。</span></label><p class="muted">重复模板会一并保存，下次仍需选择保留版本。下载的是 JSON 工程文件，不是申报文件包。</p>`,`<button data-action="closeModal">取消</button><button class="primary" data-action="downloadProject">下载工程 JSON</button>`)}
function downloadProject(){state.preferences.includeTemplates=$('#includeProjectTemplates').checked;const packed={kind:'IMO-PROJECT',schema:1,savedAt:new Date().toISOString(),includesTemplates:state.preferences.includeTemplates,state,config:CONFIG,templates:state.preferences.includeTemplates?[...templates].flatMap(([id,list])=>list.map(e=>({id,name:e.name,base64:toBase64(e.bytes)}))):[]};download(JSON.stringify(packed,null,2),'IMO_工程_'+safeName(state.ship.name||'未命名')+'.json','application/json');closeModal();toast('工程已下载；'+(packed.includesTemplates?'包含原始模板。':'不含模板，恢复时使用已载入模板，请核对版本。'))}
function cleanObject(o,depth=0){if(depth>25)throw Error('工程嵌套过深');if(Array.isArray(o)){if(o.length>10000)throw Error('工程记录过多');return o.map(v=>cleanObject(v,depth+1))}if(o&&typeof o==='object'){const out={};for(const [k,v]of Object.entries(o)){if(['__proto__','constructor','prototype'].includes(k))continue;out[k]=cleanObject(v,depth+1)}return out}return o}
async function parseProjectFile(file){
 if(file.size>60*1024*1024)throw Error('工程文件超过 60MB');
 const p=cleanObject(JSON.parse(await file.text()));
 if(p.kind!=='IMO-PROJECT'||p.schema!==1||!p.state)throw Error('不是当前版本 IMO 工程');
 const cfg=checkConfiguration(p.config||BASE_CONFIG),blank=blankState(),incoming=p.state;
 if(typeof validateProjectExtras==='function')validateProjectExtras(incoming);
 for(const k of Object.keys(blank)){
  if(incoming[k]===undefined)continue;
  if(Array.isArray(blank[k])){if(!Array.isArray(incoming[k]))throw Error('工程字段 '+k+' 应为数组');blank[k]=incoming[k]}
  else if(blank[k]&&typeof blank[k]==='object'){
   if(!incoming[k]||typeof incoming[k]!=='object'||Array.isArray(incoming[k]))throw Error('工程字段 '+k+' 应为对象');
   blank[k]={...blank[k],...incoming[k]};
  }
  else{if(typeof incoming[k]!==typeof blank[k])throw Error('工程字段 '+k+' 类型无效');blank[k]=incoming[k]}
 }
 if(typeof blank.ship.confirmed!=='boolean')throw Error('船舶确认状态应为 true / false');
 const ids=new Set();for(const person of blank.people){
  if(!person||typeof person.id!=='string'||!person.id||ids.has(person.id))throw Error('船员档案标识重复或缺失');ids.add(person.id);
  if(person.vaccines!==undefined&&(!person.vaccines||typeof person.vaccines!=='object'||Array.isArray(person.vaccines)))throw Error('疫苗档案格式无效');
 }
 for(const side of ['arrival','departure'])for(const e of blank[side]){
  if(!e||typeof e.personId!=='string'||!ids.has(e.personId))throw Error('本次名单引用了不存在的人员');
  if(!e.overrides)e.overrides={};if(typeof e.overrides!=='object'||Array.isArray(e.overrides))throw Error('本次名单覆盖值无效');
 }
 for(const key of ['ports','stores','passengers','medicines','cases']){
  const rowIds=new Set();for(const row of blank[key]){if(!row||typeof row.id!=='string'||!row.id||rowIds.has(row.id))throw Error(key+' 记录标识重复或缺失');rowIds.add(row.id)}
 }
 if(!Array.isArray(blank.preferences.signatureAnchors))throw Error('签名图片设置无效');
 if(p.templates!==undefined&&!Array.isArray(p.templates))throw Error('工程模板列表无效');
 const newTemplates=new Map();for(const t of p.templates||[]){
  if(!Number.isInteger(t.id)||t.id<1||t.id>10||typeof t.name!=='string'||typeof t.base64!=='string')throw Error('工程模板无效');
  const bytes=fromBase64(t.base64),book=await readBook(bytes,t.name);if(!newTemplates.has(t.id))newTemplates.set(t.id,[]);
  newTemplates.get(t.id).push({bytes,book,name:t.name,token:uid()});
 }
 return {packed:p,state:blank,config:cfg,templates:p.includesTemplates?newTemplates:null};
}
async function loadProject(file){
 const parsed=await parseProjectFile(file),p=parsed.packed;
 CONFIG=parsed.config;state=parsed.state;if(parsed.templates)templates=parsed.templates;importProblems=[];changed();currentView='check';closeModal();render();
 toast('工程已恢复；'+(p.includesTemplates?'已恢复原始模板。':'工程不含模板，请确认当前模板或重新选择。'));
}
async function manageSignatures(){const rows=[];for(const [id,list]of templates){if(list.length!==1)continue;const e=list[0];for(const path of Object.keys(e.book.zip.files).filter(p=>/^xl\/drawings\/drawing\d+\.xml$/.test(p))){const d=parseXML(await e.book.zip.file(path).async('string'));const relfile=e.book.zip.file(relPath(path)),rels=relfile?parseXML(await relfile.async('string')):null;for(const a of [...d.documentElement.children]){const pic=[...a.getElementsByTagNameNS('*','pic')][0];if(!pic)continue;const prop=[...pic.getElementsByTagNameNS('*','cNvPr')][0],blip=[...pic.getElementsByTagNameNS('*','blip')][0],rid=blip?.getAttributeNS(NS.r,'embed'),relation=rels?relEls(rels).find(r=>r.getAttribute('Id')===rid):null;let data='';if(relation){const p=resolvePath(path,relation.getAttribute('Target'));if(e.book.zip.file(p))data='data:image/'+(p.endsWith('.png')?'png':'jpeg')+';base64,'+await e.book.zip.file(p).async('base64')}rows.push({id,path,picId:prop?.getAttribute('id')||'',name:prop?.getAttribute('name')||'',data})}}}
 modal('图片与签名管理',`<p>只有明确标记为签名的图片受“沿用签名图片”选项控制。未标记的船公司标识始终保留。此批模板实际图片为相同公司标识。</p><div class="tablewrap"><table><thead><tr><th>标记为签名</th><th>图片</th><th>模板 / 绘图 / ID</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input type="checkbox" data-signature-index="${i}" ${state.preferences.signatureAnchors.some(s=>s.templateId===r.id&&s.path===r.path&&String(s.ids).split(',').includes(r.picId))?'checked':''}></td><td>${r.data?`<img alt="模板原图片" src="${r.data}" style="max-width:150px;max-height:80px;background:#eef2f7">`:'无法预览'}</td><td>${r.id} · ${esc(r.path)} · ${esc(r.picId)}<br>${esc(r.name)}</td></tr>`).join('')||'<tr><td colspan="3">尚无可检查的图片。</td></tr>'}</tbody></table></div>`,`<button data-action="closeModal">取消</button><button class="primary" data-action="applySignatureMarks">保存标记</button>`);window.signatureRows=rows;
}
