function enhanceView(){
 const folder=document.querySelector('[data-action=pickFolder]');if(folder&&!('webkitdirectory' in document.getElementById('templateFolder')))folder.hidden=true;
 const table=document.querySelector('[data-grid]');if(table&&!['effects','vaccines'].includes(table.dataset.grid)){const view=table.dataset.grid;const add=document.querySelector('[data-action=addRow][data-view="'+view+'"]');if(add)add.insertAdjacentHTML('afterend','<button class="danger" data-action="clearTable" data-view="'+view+'">清空本表记录</button>')}
}
actions.clearTable=el=>{const view=el.dataset.view;modal('清空表格记录','<p>将清空 '+esc(viewTitle(view))+' 中的 '+getRows(view).length+' 条记录。需要保留时请先保存工程。</p>', '<button data-action="closeModal">取消</button><button class="danger" data-action="confirmClearTable" data-view="'+view+'">清空记录</button>')};
actions.confirmClearTable=el=>{const view=el.dataset.view;if(view==='profiles'){if(state.arrival.length||state.departure.length||state.cases.some(r=>r.personId))throw Error('船员档案仍被名单或病例关联，请先移除关联。');state.people=[];state.effects={}}else state[view]=[];changed();closeModal();render()};
aliases.personId=['人员标识','personid','stableid','id'];
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=actions[el.dataset.action];if(!action)return;try{const result=action(el);if(result?.catch)result.catch(err=>modal('操作未完成','<div class="errorbox">'+esc(err.message)+'</div>'))}catch(err){console.error(err);modal('操作未完成','<div class="errorbox">'+esc(err.message)+'</div>')}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.bind){setPath(state,el.dataset.bind,el.type==='checkbox'?el.checked:el.value);if(el.dataset.bind.startsWith('ship.')&&el.dataset.bind!=='ship.confirmed')state.ship.confirmed=false;if(el.dataset.bind.startsWith('ship.')&&el.dataset.bind!=='ship.confirmed'){const confirmed=document.querySelector('[data-bind="ship.confirmed"]');if(confirmed)confirmed.checked=false}changed()}else if(el.dataset.table){try{mutateCell(el.dataset.table,el.dataset.id,el.dataset.field,el.value);if(dateFields.has(el.dataset.field)&&el.value&&!dateValue(el.value)&&!isNil(el.value)&&!/^(lifelong|lifetime|终身)$/i.test(el.value))el.style.borderColor='#c74d58';else el.style.borderColor=''}catch(err){toast(err.message)}}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.declaration){state.declarations[el.dataset.declaration]=el.value;changed()}if(el.dataset.preview)previewFile(+el.dataset.preview,+el.value);if(['importSheet','importHeader','importHasHeader','importEnd'].includes(el.id)){if(el.id==='importSheet'){importContext.sheet=+el.value;importContext.header=1;importContext.end=importContext.matrices[importContext.sheet].rows.length}else if(el.id==='importHeader')importContext.header=Math.max(1,+el.value||1);else if(el.id==='importEnd')importContext.end=Math.min(importContext.matrices[importContext.sheet].rows.length,Math.max(1,+el.value||1));else importContext.hasHeader=el.value==='1';renderImportDialog()}if(el.dataset.bind&&el.tagName==='SELECT'){if(el.dataset.bind==='voyage.mode')render()}});
document.addEventListener('paste',e=>{const target=e.target;if(!target.dataset.table||target.readOnly)return;const text=e.clipboardData?.getData('text/plain');if(!text||!/[\t\r\n]/.test(text))return;if(target.tagName==='TEXTAREA'&&target.dataset.field==='remarks'&&!text.includes('\t'))return;e.preventDefault();try{applyGridPaste(target,text)}catch(err){modal('粘贴未完成','<div class="errorbox">'+esc(err.message)+'</div>')}});
$('#templateFiles').addEventListener('change',e=>{const files=[...e.target.files];e.target.value='';task(()=>acceptTemplates(files))});$('#templateFolder').addEventListener('change',e=>{const files=[...e.target.files];e.target.value='';task(()=>acceptTemplates(files))});$('#projectFile').addEventListener('change',e=>{const f=e.target.files[0];e.target.value='';if(f)task(()=>loadProject(f))});$('#dataFile').addEventListener('change',e=>{const f=e.target.files[0];e.target.value='';if(f)task(()=>openDataImport(f,pendingDataView))});$('#mappingFile').addEventListener('change',e=>{const f=e.target.files[0];e.target.value='';if(f)task(async()=>{CONFIG=checkConfiguration(cleanObject(JSON.parse(await f.text())));changed();render();toast('映射已导入。')})});
